def _json_safe(o):
    """Recursively coerce a result dict for JSON serialization.

    The PPP result dict carries numpy floats and (after a divergence) inf /
    huge finite values.  stdlib json.dumps raises on inf/nan and FastAPI's
    JSONResponse does too, which made /api/ppp return a 500 Internal Server
    Error for every cycle once the EKF diverged.  This converts numpy
    scalars to Python, and inf/nan to None so the dashboard can render a
    '--' instead of crashing.  Huge-but-finite floats (e.g. 1e154 from a
    diverged state) are clamped to a sentinel so they do not serialize as
    a 300-digit string.
    """
    if isinstance(o, dict):
        # Underscore-prefixed keys are internal diagnostics (_traj,
        # _damp_dxu_log, _prior_pull_log, ...) consumed only by offline
        # replay through the in-process _run_ekf return — they must not
        # leak into /api/ppp responses or the persisted last_ppp_result
        # (~5k floats per arm otherwise).  o.copy() is GIL-atomic and
        # snapshots the items: the solve thread mutates latest_result in
        # place (e.g. injecting "rtk_easn"), which otherwise raises
        # "dictionary changed size during iteration" mid-serialisation.
        return {k: _json_safe(v) for k, v in o.copy().items()
                if not (isinstance(k, str) and k.startswith("_"))}
    if isinstance(o, (list, tuple)):
        return [_json_safe(v) for v in o]
    if isinstance(o, np.ndarray):
        return [_json_safe(v) for v in o.tolist()]
    if isinstance(o, (np.floating,)):
        o = float(o)
    elif isinstance(o, (np.integer,)):
        return int(o)
    elif isinstance(o, (np.bool_,)):
        return bool(o)
    if isinstance(o, float):
        if not math.isfinite(o):
            return None
        # Clamp absurd magnitudes from a diverged state to a recognizable
        # sentinel rather than emitting a 300-digit number.
        if abs(o) > 1e9:
            return None
        return o
    return o


def _parse_obs_date_safe(obs_path: Path) -> tuple[int | None, int | None, int | None]:
    """Parse TIME OF FIRST OBS from a RINEX obs header (any version).

    Returns (year, month, day) or (None, None, None) on failure.
    """
    try:
        with open(obs_path, "r", errors="ignore") as f:
            for line in f:
                if "TIME OF FIRST OBS" in line:
                    parts = line.split()
                    year = int(parts[0])
                    if year < 80:
                        year += 2000
                    elif year < 100:
                        year += 1900
                    return year, int(parts[1]), int(parts[2])
    except Exception:
        pass
    return None, None, None


def _find_brdc_nav_files(obs_path: Path | None = None,
                         year: int | None = None,
                         doy: int | None = None) -> list[Path]:
    """Find BRDC broadcast nav file(s) covering the observation date.

    RINEX 2.11 broadcast nav files are named ``brdc<DOY>0.<yy>n`` (e.g.
    ``brdc2500.26n`` for DOY 250 of 2026).  A multi-hour capture crossing
    UTC midnight spans two DOYs, so both days' BRDC files are returned.

    If *year*/*doy* are not supplied, they are parsed from the RINEX obs
    header.  Falls back to the most recent BRDC files in the nav directory
    when the exact date cannot be determined.
    """
    nav_dir = _PROJECT_ROOT / "data" / "rinex" / "nav"
    if not nav_dir.exists():
        return []
    if year is None or doy is None:
        if obs_path is not None:
            y, m, d = _parse_obs_date_safe(obs_path)
            if y is not None:
                import datetime as _dt
                year = y
                doy = (_dt.datetime(y, m, d) - _dt.datetime(y, 1, 1)).days + 1
    results: list[Path] = []
    if year is not None and doy is not None:
        yy = year % 100
        for d in (doy, doy + 1):  # current + next day (midnight crossing)
            for pat in (f"brdc{d:03d}0.{yy:02d}n", f"BRDC00IGS_R_{year}{d:03d}0000_01D_MN.rnx"):
                p = nav_dir / pat
                if p.exists():
                    results.append(p)
                    break
    if not results:
        # Fallback: most recent brdc*.??n files
        all_brdc = sorted(nav_dir.glob("brdc*.??n"),
                          key=lambda p: p.name, reverse=True)
        results = all_brdc[:2]
    return results


def _cached_clk_to_sod(clk_abs: dict, year: int, doy: int) -> dict:
    """Re-index an absolute-GPS-seconds CLK table to seconds-of-day for
    the target date.

    load_cached_clk tables are keyed by week*604800 + SOW (absolute).
    When merging one into a find_products_for_date PreciseProducts —
    whose index is seconds-of-day — the absolute keys never match SOD
    lookups, so the merged clocks would silently never be used.  Keep
    only the target date's records and fold them onto the SOD axis; the
    PreciseProducts day check then guards wrong-day lookups as usual.
    """
    import datetime as _dt
    target_day = (_dt.date(year, 1, 1) + _dt.timedelta(days=doy - 1)
                  - _dt.date(1980, 1, 6)).days
    out = {}
    for sat, arr in clk_abs.items():
        keep = (arr[:, 0] // 86400.0) == target_day
        if int(keep.sum()) >= 2:
            out[sat] = np.column_stack(
                (arr[keep, 0] % 86400.0, arr[keep, 1]))
    return out

