@app.get("/", response_class=HTMLResponse)
async def index():
    index_path = _static_dir / "index.html"
    return index_path.read_text(encoding="utf-8")


@app.get("/api/fix")
async def api_fix():
    if _reader is None:
        return {"error": "GPS reader not initialised"}
    fix = _reader.get_fix()
    data = _fix_to_dict(fix)
    if _tep_processor:
        data["tep"] = _tep_processor.tep_data
    if _kriging_proxy:
        data["kriging"] = _kriging_proxy.get_data()
    if _ppp_processor:
        data["ppp"] = _json_safe(_ppp_processor.latest_result)
    return data


@app.get("/api/kriging")
async def api_kriging():
    if _kriging_proxy:
        return JSONResponse(_kriging_proxy.get_data())
    return {"available": False}


@app.get("/api/ppp")
async def api_ppp():
    if _ppp_processor:
        cached = getattr(_ppp_processor, "_latest_result_json", None)
        if cached is not None:
            return Response(content=cached, media_type="application/json")
        return JSONResponse(_json_safe(_ppp_processor.latest_result or {"available": False}))
    return {"available": False}


_skill_history_cache = {"mtime": 0.0, "last_file": "", "payload": None}


@app.get("/api/skill_history")
async def api_skill_history():
    """Serve rolling archive history + latest holdout curves + station map for the Skill Observatory dashboard."""
    try:
        res_dir = _PROJECT_ROOT / "data" / "ppp_live" / "results"
        if not res_dir.exists():
            return {"available": False}
        json_files = sorted(res_dir.glob("last_result_window_*.json"))
        if not json_files:
            return {"available": False}
        latest_json = json_files[-1]
        latest_mtime = latest_json.stat().st_mtime
        if (_skill_history_cache["payload"] is not None
                and _skill_history_cache["last_file"] == latest_json.name
                and abs(_skill_history_cache["mtime"] - latest_mtime) < 0.5):
            return JSONResponse(_skill_history_cache["payload"])

        windows = []
        for jf in json_files[-160:]:
            try:
                d = json.loads(jf.read_text(encoding="utf-8"))
                cp = d.get("clock_prediction") or {}
                af = cp.get("alpha_fit") or {}
                cr = af.get("causal_ridge") or {}
                pd = d.get("position_degraded") or {}
                fs = d.get("position_fullsky") or {}
                ar = d.get("ppp_ar") or {}
                win_id = jf.stem.replace("last_result_window_", "")
                dep_pct = cp.get("tep_vs_persist_pct_deployed")
                if dep_pct is None:
                    dep_pct = cp.get("tep_causal_vs_persist_pct")
                dep_clk = (cp.get("tep_rmse_deployed_m")
                           if cp.get("tep_rmse_deployed_m") is not None
                           else cp.get("tep_causal_rmse_m"))
                if cp.get("network_method") == "instantaneous_residual_fallback":
                    rs_c = d.get("clock_rescore") or {}
                    if (rs_c.get("method") == "step96_accumulated_offset"
                            and rs_c.get("tep_vs_persist_pct_deployed") is not None):
                        dep_pct = rs_c.get("tep_vs_persist_pct_deployed")
                        if cp.get("persist_rmse_m") is not None:
                            dep_clk = round(
                                float(cp["persist_rmse_m"])
                                * (1.0 - float(dep_pct) / 100.0), 4)
                    else:
                        dep_pct = 0.0
                        dep_clk = cp.get("persist_rmse_m")
                windows.append({
                    "id": win_id,
                    "timestamp": d.get("timestamp"),
                    "k": pd.get("k"),
                    "free_clk_m": cp.get("free_rmse_m"),
                    "persist_clk_m": cp.get("persist_rmse_m"),
                    "dep_clk_m": dep_clk,
                    "fixed_causal_clk_m": cp.get("tep_causal_rmse_m"),
                    "oracle_clk_m": cp.get("tep_rmse_m"),
                    "dep_gain_pct": dep_pct,
                    "fixed_causal_pct": cp.get("tep_causal_vs_persist_pct"),
                    "persist_vs_free_pct": cp.get("persist_vs_free_pct"),
                    "dep_ns": (cp.get("tep_rmse_deployed_ns")
                               if cp.get("tep_rmse_deployed_ns") is not None
                               else (round(cp["tep_causal_rmse_m"] / 299792458.0 * 1e9, 2)
                                     if cp.get("tep_causal_rmse_m") is not None else None)),
                    "free_ns": cp.get("free_rmse_ns"),
                    "persist_ns": cp.get("persist_rmse_ns"),
                    "pos_3d_m": pd.get("tep_rmse_3d_m"),
                    "free_3d_m": pd.get("free_rmse_3d_m"),
                    "conv_3d_m": fs.get("converged_rmse_3d_m") or fs.get("rmse_3d_m"),
                    "ar_conv_m": ar.get("fixed_converged_rmse_3d_m"),
                    "ar_fix_rate": ar.get("fix_rate"),
                    "n_feat": cr.get("n_feat"),
                    "n_win": cr.get("n_win"),
                    "ridge_rms_m": cr.get("ridge_rms_m"),
                    "stack_rms_m": cr.get("stack_rms_m"),
                    "dep_rms_m": cr.get("dep_rms_m"),
                    "taper_mean": cr.get("taper_mean"),
                    "lam": cr.get("lam"),
                    "hl": cr.get("hl"),
                    "cap_m": cr.get("cap_m"),
                })
            except Exception:
                continue

        # Summary statistics across windows that have dep_gain_pct
        gains = [float(w["dep_gain_pct"]) for w in windows
                 if w.get("dep_gain_pct") is not None]
        gains_sorted = sorted(gains)
        n_g = len(gains)
        summary = {
            "n_windows": n_g,
            "mean_gain_pct": round(float(np.mean(gains)), 2) if n_g else 0.0,
            "median_gain_pct": round(float(np.median(gains_sorted)), 2) if n_g else 0.0,
            "p90_gain_pct": round(float(np.percentile(gains_sorted, 90)), 2) if n_g else 0.0,
            "max_gain_pct": round(float(max(gains)), 2) if n_g else 0.0,
            "min_gain_pct": round(float(min(gains)), 2) if n_g else 0.0,
            "win_count": int(sum(1 for g in gains if g > 0.0)),
            "win_rate_pct": round(100.0 * sum(1 for g in gains if g > 0.0) / n_g, 1) if n_g else 0.0,
        }

        # Extract latest holdout curves + station map from latest raw_window_*.pkl
        holdout = {}
        stations = []
        rx_lat, rx_lon = 53.63995, 0.10305
        try:
            d_last = json.loads(latest_json.read_text(encoding="utf-8"))
            ng = d_last.get("network_geometry") or {}
            if ng.get("receiver_lat") is not None:
                rx_lat = float(ng["receiver_lat"])
                rx_lon = float(ng["receiver_lon"])
            pkl_path = res_dir / f"raw_window_{latest_json.stem.replace('last_result_window_', '')}.pkl"
            if not pkl_path.exists():
                pkls = sorted(res_dir.glob("raw_window_*.pkl"))
                pkl_path = pkls[-1] if pkls else None
            if pkl_path and pkl_path.exists():
                import pickle
                p = pickle.loads(pkl_path.read_bytes())
                t_pre = np.asarray(
                    p["t_pre"] if p.get("t_pre") is not None else [], float)
                t_ho = np.asarray(
                    p["t_ho"] if p.get("t_ho") is not None else [], float)
                b_ho = np.asarray(
                    p["b_ho"] if p.get("b_ho") is not None else [], float)
                p_pred = np.asarray(
                    p["persist_pred"] if p.get("persist_pred") is not None else [], float)
                dep_m = p.get("dep_m")
                if len(t_ho) > 10 and len(b_ho) == len(t_ho) and len(p_pred) == len(t_ho):
                    t0_val = float(t_pre[-1]) if len(t_pre) else float(t_ho[0])
                    h_s = t_ho - t0_val
                    r_persist = b_ho - p_pred  # realized clock deviation from persistence
                    if dep_m is not None and len(dep_m) == len(t_ho):
                        dep_arr = np.asarray(dep_m, float)
                    else:
                        cp_last = d_last.get("clock_prediction") or {}
                        tps = cp_last.get("tep_pred_series_m")
                        if tps and len(tps) == len(t_ho):
                            dep_arr = np.asarray(tps, float) - p_pred
                        else:
                            dep_arr = np.zeros_like(h_s)
                    r_tep = b_ho - (p_pred + dep_arr)  # residual clock error after TEP correction
                    idx = np.unique(np.linspace(0, len(h_s) - 1, min(360, len(h_s))).astype(int))
                    holdout = {
                        "window_id": pkl_path.stem.replace("raw_window_", ""),
                        "h_s": [round(float(x), 1) for x in h_s[idx]],
                        "truth_dev_m": [round(float(x), 4) for x in r_persist[idx]],
                        "tep_corr_m": [round(float(x), 4) for x in dep_arr[idx]],
                        "residual_after_tep_m": [round(float(x), 4) for x in r_tep[idx]],
                        "persist_rmse_m": round(float(np.sqrt(np.mean(r_persist ** 2))), 4),
                        "tep_dep_rmse_m": round(float(np.sqrt(np.mean(r_tep ** 2))), 4),
                    }
                    # Build station distance & correlation profile
                    rs = p.get("raw_series") or {}
                    sc = p.get("station_coords") or {}
                    t0_sod = t0_val % 86400.0
                    r0_d = (p_pred - b_ho) - float(np.mean(p_pred - b_ho))
                    for st, tup in rs.items():
                        try:
                            if st not in sc or sc[st] is None:
                                continue
                            lat, lon = float(sc[st][0]), float(sc[st][1])
                            if lon > 180.0:
                                lon -= 360.0
                            p1, p2 = math.radians(rx_lat), math.radians(lat)
                            dp_r = math.radians(lat - rx_lat)
                            dl_r = math.radians(lon - rx_lon)
                            a_h = (math.sin(dp_r / 2.0) ** 2
                                   + math.cos(p1) * math.cos(p2) * math.sin(dl_r / 2.0) ** 2)
                            dist_km = 2.0 * 6371.0 * math.asin(math.sqrt(max(0.0, min(1.0, a_h))))
                            y_az = math.sin(dl_r) * math.cos(p2)
                            x_az = (math.cos(p1) * math.sin(p2)
                                    - math.sin(p1) * math.cos(p2) * math.cos(dl_r))
                            az_deg = (math.degrees(math.atan2(y_az, x_az)) + 360.0) % 360.0
                            ts = np.asarray(tup[0], float)
                            vs = np.asarray(tup[1], float)
                            m_fin = np.isfinite(vs)
                            if int(m_fin.sum()) < 50 or len(ts) < 2:
                                continue
                            tl = float(ts[-1])
                            a_unw = tl - (((tl % 86400.0) - t0_sod + 43200.0) % 86400.0 - 43200.0)
                            c_ho = np.interp(a_unw + h_s, ts[m_fin], vs[m_fin])
                            cd = c_ho - float(np.mean(c_ho))
                            sd = float(np.std(cd))
                            corr = (float(np.corrcoef(cd, -r0_d)[0, 1])
                                    if (sd > 1e-6 and float(np.std(r0_d)) > 1e-6) else 0.0)
                            if not math.isfinite(corr):
                                corr = 0.0
                            stations.append({
                                "id": st,
                                "lat": round(lat, 4),
                                "lon": round(lon, 4),
                                "dist_km": round(dist_km, 1),
                                "az_deg": round(az_deg, 1),
                                "n_samples": int(m_fin.sum()),
                                "rms_m": round(sd, 3),
                                "corr": round(corr, 3),
                                "band": ("near_uk" if dist_km < 360.0
                                         else ("mid_eu" if dist_km < 900.0 else "far_iberia")),
                            })
                        except Exception:
                            continue
                    stations.sort(key=lambda s: s["dist_km"])
        except Exception as e:
            logger.debug("skill_history holdout/station extraction failed: %s", e)

        attribution = None
        try:
            attr_path = res_dir / "tep_attribution.json"
            if attr_path.exists():
                attribution = json.loads(attr_path.read_text(encoding="utf-8"))
        except Exception:
            attribution = None

        payload = _json_safe({
            "available": True,
            "summary": summary,
            "receiver": {"lat": rx_lat, "lon": rx_lon},
            "windows": windows,
            "holdout": holdout,
            "stations": stations,
            "attribution": attribution,
        })
        _skill_history_cache["mtime"] = latest_mtime
        _skill_history_cache["last_file"] = latest_json.name
        _skill_history_cache["payload"] = payload
        return JSONResponse(payload)
    except Exception as e:
        logger.error("api_skill_history error: %s", e)
        return JSONResponse({"available": False, "error": str(e)})


@app.websocket("/ws")
async def ws_endpoint(ws: WebSocket):
    await ws.accept()
    try:
        while True:
            if _reader is None:
                await ws.send_json({"error": "no reader"})
                await asyncio.sleep(1)
                continue

            fix = _reader.get_fix()
            data = _fix_to_dict(fix)
            data["nmea_count"] = _reader.nmea_count
            data["mtk_count"] = _reader.mtk_count
            data["ubx_count"] = _reader.ubx_count
            data["error_count"] = _reader.error_count
            data["last_read_age"] = time.time() - _reader.last_read_time if _reader.last_read_time else 999

            # TEP NMEA smoothing (visualization — not a TEP proof)
            if _tep_processor:
                tep_data = _tep_processor.update(fix)
                data["tep"] = tep_data

            # TEP kriging (real proof — clock bias prediction from NTRIP network)
            if _kriging_proxy:
                data["kriging"] = _kriging_proxy.get_data()

            # PPP on raw RTCM3 (real proof — EKF with/without TEP clock prior)
            if _ppp_processor:
                data["ppp"] = _json_safe(_ppp_processor.latest_result)

            await ws.send_json(_json_safe(data))
            await asyncio.sleep(1.0)
    except WebSocketDisconnect:
        pass
    except Exception as e:
        logger.error("WebSocket error: %s", e)


def _fix_to_dict(fix: GPSFix) -> dict:
    sats = []
    for sat in sorted(fix.satellites.values(), key=lambda s: (-s.snr if s.snr > 0 else 999, s.prn)):
        sats.append({
            "prn": sat.prn,
            "elevation": round(sat.elevation, 1),
            "azimuth": round(sat.azimuth, 1),
            "snr": round(sat.snr, 1) if sat.snr > 0 else 0,
            "used": sat.used_in_fix,
        })

    return {
        "fix_type": fix.fix_type,
        "fix_quality": fix.fix_quality,
        "has_fix": fix.has_fix,
        "latitude": round(fix.latitude, 8),
        "longitude": round(fix.longitude, 8),
        "altitude": round(fix.altitude, 2),
        "num_sats": fix.num_satellites,
        "hdop": round(fix.hdop, 2),
        "vdop": round(fix.vdop, 2),
        "pdop": round(fix.pdop, 2),
        "speed_knots": round(fix.speed_knots, 2),
        "course": round(fix.course, 1),
        "utc_time": fix.datetime_utc.strftime("%H:%M:%S") if fix.datetime_utc else "--:--:--",
        "utc_date": fix.datetime_utc.strftime("%Y-%m-%d") if fix.datetime_utc else "----:--:--",
        "satellites": sats,
    }


def _set_proc_name(name: str) -> None:
    """Set the kernel comm name so earlyoom's --avoid regex matches us.

    The systemd unit launches ``python3``, so /proc/<pid>/comm is
    "python3" — which does NOT match earlyoom's
    ``--avoid '^(tep-gps-web|tep-kriging|gps_web|...)'`` regex, and the
    daemon SIGKILLed a mid-solve gps_web at ~4.9% free mem (2026-09-28,
    journal earlyoom[529]).  prctl(PR_SET_NAME) writes comm, the exact
    field earlyoom regex-matches.  No-op off Linux.
    """
    try:
        import ctypes
        ctypes.CDLL("libc.so.6").prctl(15, name.encode()[:15], 0, 0, 0)
    except Exception:
        pass


def main():
    import argparse

    _set_proc_name("tep-gps-web")

    logging.basicConfig(level=getattr(logging, _env_str("LOG_LEVEL", "INFO").upper(), logging.INFO),
                        format="%(asctime)s %(levelname)s [%(name)s] %(message)s")
    # Also log to the live log file so output is captured even when
    # stdout/stderr are redirected to a socket (e.g. by a service manager).
    # Skip the handler when stdout/stderr already append to that very
    # file (the tep-gps-web.sh wrapper does `>> gps_web.log 2>&1`) —
    # otherwise every line lands twice and the log grows 2x.
    _log_dir = _PROJECT_ROOT / "logs" / "live"
    _log_dir.mkdir(parents=True, exist_ok=True)
    _log_path = _log_dir / "gps_web.log"
    _dup = False
    try:
        _lst = os.stat(_log_path)
        _dup = any((os.fstat(fd).st_dev, os.fstat(fd).st_ino)
                   == (_lst.st_dev, _lst.st_ino) for fd in (1, 2))
    except OSError:
        pass
    if not _dup:
        from logging.handlers import RotatingFileHandler
        _file_handler = RotatingFileHandler(
            _log_path, maxBytes=50 * 1024 * 1024, backupCount=3)
        _file_handler.setLevel(getattr(logging, _env_str("LOG_LEVEL", "INFO").upper(), logging.INFO))
        _file_handler.setFormatter(logging.Formatter("%(asctime)s %(levelname)s [%(name)s] %(message)s"))
        logging.getLogger().addHandler(_file_handler)
    # The kriging proxy polls every 5 s for hours; at INFO that is one log
    # line per poll and the actual results become impossible to find.
    for noisy in ("httpx", "httpcore", "urllib3"):
        logging.getLogger(noisy).setLevel(logging.WARNING)

    # Every flag has a matching environment variable, following the rpi/
    # convention documented in README.md, so tep_pi_service.py can drive this
    # script the same way it drives its siblings.  The serial-port default
    # comes from GPS_SERIAL_PORT (the Pi's /dev/serial0), not a hardcoded
    # macOS device node.
    parser = argparse.ArgumentParser(description="TEP-PPP GPS Web Dashboard")
    parser.add_argument("--port", default=_default_serial_port(),
                        help="Serial port [env GPS_SERIAL_PORT]; "
                             "auto-detected from /dev if unset")
    parser.add_argument("--baud", type=int, default=_env_int("GPS_BAUDRATE", 115200),
                        help="Baud rate [env GPS_BAUDRATE]")
    parser.add_argument("--host", default=_env_str("WEB_HOST", "127.0.0.1"),
                        help="Web server host [env WEB_HOST]. Defaults to "
                             "loopback; the dashboard has no authentication, "
                             "so bind 0.0.0.0 only on a trusted network.")
    parser.add_argument("--web-port", type=int, default=_env_int("WEB_PORT", 8000),
                        help="Web server port [env WEB_PORT]")
    parser.add_argument("--raw", action="store_true",
                        default=_env_str("GPS_ENABLE_RAW", "0") == "1",
                        help="Enable raw output [env GPS_ENABLE_RAW=1]")
    parser.add_argument("--no-tep", action="store_true",
                        default=_env_str("TEP_ENABLED", "1") == "0",
                        help="Disable TEP NMEA smoothing [env TEP_ENABLED=0]")
    parser.add_argument("--kriging-url", default=_env_str("TEP_KRIGING_URL", "http://localhost:8765"),
                        help="URL of TEP kriging server [env TEP_KRIGING_URL]")
    parser.add_argument("--no-kriging", action="store_true",
                        default=_env_str("TEP_KRIGING_ENABLED", "1") == "0",
                        help="Disable kriging proxy [env TEP_KRIGING_ENABLED=0]")
    # The TEP experiment runs BY DEFAULT, at settings that can actually show
    # the effect.  Disable with --no-ppp.
    parser.add_argument("--ppp", action="store_true", default=True,
                        help="Run the TEP experiment on raw RTCM3 (default on; "
                             "requires RTKLIB) [env TEP_PPP_ENABLED=0 to disable]")
    parser.add_argument("--no-ppp", dest="ppp", action="store_false",
                        help="Disable the PPP/TEP experiment")
    parser.set_defaults(ppp=_env_str("TEP_PPP_ENABLED", "1") == "1")
    parser.add_argument("--ppp-capture", type=int,
                        default=_env_int("TEP_PPP_CAPTURE_S", 14400),
                        help="Rolling analysis WINDOW in seconds "
                             "[env TEP_PPP_CAPTURE_S]. Default 14400 (4 h) = "
                             "step_106's optimal outage. Below 2000 s the "
                             "capture is outside the TEP band and cannot show "
                             "the effect at all.")
    parser.add_argument("--ppp-chunk", type=int,
                        default=_env_int("TEP_PPP_CHUNK_S", 900),
                        help="Capture chunk in seconds [env TEP_PPP_CHUNK_S]. "
                             "The window is re-scored after every chunk, so "
                             "this is how often new numbers appear.")
    parser.add_argument("--ppp-interval", type=int,
                        default=_env_int("TEP_PPP_INTERVAL_S", 0),
                        help="Idle gap between chunks (default 0 = continuous)")
    parser.add_argument("--ref-ecef", default=_env_str("TEP_REF_ECEF", ""),
                        help="Surveyed truth position as 'X,Y,Z' ECEF metres "
                             "[env TEP_REF_ECEF].  Strongly recommended: "
                             "without it the position truth is the session "
                             "running mean, valid only for a static receiver.")
    parser.add_argument("--sweep", action="store_true",
                        default=_env_str("TEP_SWEEP_ENABLED", "0") == "1",
                        help="Run the full TEP configuration sweep "
                             "(262 configs) after each cycle "
                             "[env TEP_SWEEP_ENABLED=1]")
    args = parser.parse_args()

    # Claim the dashboard port BEFORE opening the serial port or touching
    # the shared working directory.
    #
    # uvicorn binds last, so a duplicate launch used to get all the way
    # through startup -- seizing the GPS serial port from the live process
    # on the way -- before dying on "address already in use" and unwinding
    # through a cleanup that deleted the live run's files.  Failing here
    # instead makes a redundant restart a no-op for the running rig.
    _probe = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    _probe.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    try:
        _probe.bind((args.host, args.web_port))
    except OSError as e:
        logger.error("Port %s:%d is already in use (%s) -- another instance "
                     "is serving the dashboard. Exiting without touching the "
                     "serial port or %s.",
                     args.host, args.web_port, e,
                     _PROJECT_ROOT / "data" / "ppp_live")
        return 1
    finally:
        _probe.close()

    ref_ecef = None
    if args.ref_ecef:
        try:
            parts = [float(v) for v in args.ref_ecef.replace(" ", "").split(",")]
            if len(parts) != 3:
                raise ValueError("expected three comma-separated values")
            ref_ecef = np.array(parts, float)
            logger.info("Truth reference: surveyed ECEF %s", ref_ecef.tolist())
        except Exception as e:
            logger.error("Invalid --ref-ecef %r (%s) — falling back to the "
                         "session running mean", args.ref_ecef, e)
            ref_ecef = None

    global _reader, _tep_processor, _kriging_proxy, _ppp_processor
    _reader = GPSReader(args.port, args.baud, enable_raw=args.raw)
    _reader.start()

    if not args.no_tep:
        _tep_processor = TEPProcessor()
        logger.info("TEP NMEA smoothing enabled (visualization mode)")

    if not args.no_kriging:
        _kriging_proxy = KrigingProxy(args.kriging_url)
        _kriging_proxy.start()
        logger.info("Kriging proxy started — polling %s", args.kriging_url)

    if args.ppp:
        # Clean up leftover scratch directories from crashed/killed runs.
        # Each PPPProcessor instance creates a tempfile.mkdtemp("tep_ppp_*")
        # and only removes it on a clean shutdown (cleanup() in the finally
        # block below).  A killed process (Ctrl-C, OOM, service
        # restart) leaves them behind — 100+ directories of raw RTCM3 and
        # RINEX can fill a Pi's SD card within a day.
        try:
            import tempfile as _tf
            _tmpdir = Path(_tf.gettempdir())
            for old in _tmpdir.glob("tep_ppp_*"):
                if old.is_dir():
                    shutil.rmtree(old, ignore_errors=True)
        except Exception:
            pass
        _ppp_processor = PPPProcessor(
            args.port, args.baud,
            capture_seconds=args.ppp_capture,
            interval_seconds=args.ppp_interval,
            gps_reader=_reader,
            kriging_proxy=_kriging_proxy if not args.no_kriging else None,
            ref_ecef=ref_ecef,
            chunk_seconds=args.ppp_chunk,
        )
        _ppp_processor.sweep_enabled = args.sweep
        _ppp_processor.start()
        band = PPPProcessor._band_status(float(args.ppp_capture))
        logger.info("TEP experiment: rolling %ds window (%s — %s), "
                    "re-scored every %ds",
                    args.ppp_capture, band["verdict"], band["note"], args.ppp_chunk)
        if not band["in_band"]:
            logger.warning("--ppp-capture %ds is OUTSIDE the TEP band; the "
                           "experiment cannot show an effect. Use >= %ds.",
                           args.ppp_capture, int(PPPProcessor.TEP_BAND_MIN_S))

    logger.info("GPS reader started on %s @ %d baud", args.port, args.baud)
    logger.info("Web dashboard: http://%s:%d", args.host, args.web_port)
    if args.host == "0.0.0.0":
        logger.warning("Bound to 0.0.0.0 — the dashboard is UNAUTHENTICATED "
                       "and exposes live position. Use only on a trusted network.")

    try:
        uvicorn.run(app, host=args.host, port=args.web_port, log_level="warning")
    finally:
        _reader.stop()
        if _kriging_proxy:
            _kriging_proxy.stop()
        if _ppp_processor:
            _ppp_processor.stop()
            _ppp_processor.cleanup()
        logger.info("GPS reader stopped")


if __name__ == "__main__":
    sys.exit(main() or 0)
